To log game events without slowing down the main loop, implement asynchronous logging using a background worker. Use a thread-safe queue to collect log messages and a separate thread to process and write logs. Here's a simple setup:

1. Create a queue for log messages.
2. Start a background worker that processes the queue.
3. Use an asynchronous function to add log messages to the queue.

Example code:

```javascript
const logQueue = [];
const fs = require('fs');

function logWorker() {
  setInterval(() => {
    if (logQueue.length > 0) {
      const message = logQueue.shift();
      fs.appendFile('game.log', message + '\n', (err) => {
        if (err) console.error('Logging error:', err);
      });
    }
  }, 100); // Adjust interval as needed
}

function logEvent(event) {
  logQueue.push(JSON.stringify(event));
}

// Start the log worker
logWorker();

// Example usage
logEvent({ type: 'player_move', position: { x: 100, y: 200 } });
```

This setup allows you to log events without blocking the main game loop.

